// Şifreli kilit: 4x4 tuş takımıyla 4 haneli şifre girilir.
// Doğru şifre: servo kilidi 5 sn açar, yeşil LED yanar.
// Yanlış şifre: kırmızı LED yanar, buzzer öter.
// # = onayla, * = sil.
#include <Keypad.h>
#include <Servo.h>
#include <LiquidCrystal.h>

const char SIFRE[] = "1234";           // Kendi şifreni yaz (4 rakam).
const unsigned long ACIK_SURE = 5000;  // ms; kilidin açık kaldığı süre
const unsigned long HATA_SURE = 1000;  // ms; yanlış şifre uyarısı
const int KILITLI_ACI = 0;
const int ACIK_ACI = 90;

const int SERVO_PIN = 10;
const int YESIL_PIN = 11;
const int KIRMIZI_PIN = 12;
const int BUZZER_PIN = 13;

// LCD: RS, E, D4, D5, D6, D7 analog pinlerde (dijital çıkış olarak).
LiquidCrystal lcd(A0, A1, A2, A3, A4, A5);

const byte SATIR = 4;
const byte SUTUN = 4;
char tuslar[SATIR][SUTUN] = {
  {'1', '2', '3', 'A'},
  {'4', '5', '6', 'B'},
  {'7', '8', '9', 'C'},
  {'*', '0', '#', 'D'}
};
byte satirPinleri[SATIR] = {9, 8, 7, 6};  // R1, R2, R3, R4
byte sutunPinleri[SUTUN] = {5, 4, 3, 2};  // C1, C2, C3, C4
Keypad tusTakimi = Keypad(makeKeymap(tuslar), satirPinleri, sutunPinleri, SATIR, SUTUN);

Servo kilit;
char girilen[5];       // 4 rakam + bitiş karakteri
byte haneSayisi = 0;

void sifreIste() {
  haneSayisi = 0;
  girilen[0] = '\0';
  lcd.clear();
  lcd.print("Sifre girin:");
  lcd.setCursor(0, 1);
}

void kilidiAc() {
  Serial.println("Dogru sifre: kilit acik");
  lcd.clear();
  lcd.print("Kapi acik");
  digitalWrite(YESIL_PIN, HIGH);
  tone(BUZZER_PIN, 1500, 150);
  kilit.write(ACIK_ACI);
  // Geri sayım.
  for (int s = ACIK_SURE / 1000; s > 0; s--) {
    lcd.setCursor(0, 1);
    lcd.print(s);
    lcd.print(" sn  ");
    delay(1000);
  }
  kilit.write(KILITLI_ACI);
  digitalWrite(YESIL_PIN, LOW);
  Serial.println("Kilit kapandi");
}

void yanlisSifre() {
  Serial.println("Yanlis sifre");
  lcd.clear();
  lcd.print("Yanlis sifre!");
  digitalWrite(KIRMIZI_PIN, HIGH);
  tone(BUZZER_PIN, 400, HATA_SURE);
  delay(HATA_SURE);
  digitalWrite(KIRMIZI_PIN, LOW);
}

void setup() {
  Serial.begin(9600);
  pinMode(YESIL_PIN, OUTPUT);
  pinMode(KIRMIZI_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  kilit.attach(SERVO_PIN);
  kilit.write(KILITLI_ACI);
  lcd.begin(16, 2);
  sifreIste();
}

void loop() {
  char tus = tusTakimi.getKey();
  if (!tus) return;

  if (tus == '*') {          // sil
    sifreIste();
    return;
  }
  if (tus == '#') {          // onayla
    if (haneSayisi == 4 && strcmp(girilen, SIFRE) == 0) kilidiAc();
    else yanlisSifre();
    sifreIste();
    return;
  }
  if (tus >= '0' && tus <= '9' && haneSayisi < 4) {
    girilen[haneSayisi] = tus;
    haneSayisi++;
    girilen[haneSayisi] = '\0';
    lcd.print('*');            // rakam gizli gösterilir
    tone(BUZZER_PIN, 2000, 30);  // tuş sesi
  }
}
